use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf}};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-joint-ring-shared176";const P:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-06-g2-joint-ring-native176";
fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}fn files(p:&Path)->Vec<PathBuf>{let mut v=vec![];for e in fs::read_dir(p).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_dir(){v.extend(files(&e.path()));}else{assert!(!e.file_type().unwrap().is_symlink());v.push(e.path());}}v.sort();v}
fn main(){let out=Path::new(P).join("artifacts/raw-profile-inventory.json");assert!(!out.exists());let a:Value=serde_json::from_slice(&fs::read(Path::new(R).join("analysis.json")).unwrap()).unwrap();let mut records=vec![];for row in a["rows"].as_array().unwrap().iter().filter(|r|r["job"]["panel"]=="cycles"){let job=&row["job"];let path=job["data"].as_str().unwrap();let bytes=fs::read(path).unwrap();let binary=job["binary"].as_str().unwrap();records.push(json!({"name":job["name"],"raw_perf_data":path,"length":bytes.len(),"sha256":hash(&bytes),"binary":binary,"binary_sha256":hash(&fs::read(binary).unwrap()),"actual_pid":row["receipt"]["pid"],"hash_scope":"postcapture preserved original raw file; no new capture or decoding"}));}assert_eq!(records.len(),6);let b=serde_json::to_vec_pretty(&json!({"profiles":records,"raw_data_not_published":true,"recordings_repeated":false})).unwrap();fs::write(&out,&b).unwrap();fs::write(Path::new(R).join("raw-profile-inventory.json"),b).unwrap();fs::copy(Path::new(R).join("inventory.rs"),Path::new(P).join("artifacts/inventory.rs")).unwrap();let path=Path::new(P).join("README.md");let mut s=fs::read_to_string(&path).unwrap();s.push_str("\nThe [raw-profile inventory](artifacts/raw-profile-inventory.json) binds the six preserved local perf.data files to their lengths, SHA-256 hashes, exact executable hashes and actual PIDs. Inventory creation occurs after recording and adds no capture or decode.\n");fs::write(path,s).unwrap();let p=Path::new(P).join("publication-review.json");let mut v:Value=serde_json::from_slice(&fs::read(&p).unwrap()).unwrap();v["raw_profile_inventory_members"]=json!(6);v["links"].as_array_mut().unwrap().push(json!("artifacts/raw-profile-inventory.json"));fs::write(p,serde_json::to_vec_pretty(&v).unwrap()).unwrap();let sums=files(Path::new(P)).into_iter().filter(|p|p.file_name().unwrap()!="SHA256SUMS").map(|p|format!("{}  {}\n",hash(&fs::read(&p).unwrap()),p.strip_prefix(P).unwrap().display())).collect::<String>();fs::write(Path::new(P).join("SHA256SUMS"),sums).unwrap();println!("Raw-profile inventory6hashes added;{}publicationfiles, original archives and recordings unchanged",files(Path::new(P)).len());}
